        IEnumerator GuardV37(IEnumerator routine)
        {
            while(true){object next=null;bool move=false;try{move=routine.MoveNext();if(move)next=routine.Current;}catch(System.Exception ex){Check(false,"native verification exception: "+ex);System.IO.File.WriteAllLines(System.IO.Path.Combine(directory,"runtime-verification.txt"),results);Application.Quit(1);yield break;}if(!move)yield break;yield return next;}
        }
